* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: #1a1c2c;
  color: #e0e0e0;
  font-family: 'Courier New', Courier, monospace;
  image-rendering: pixelated;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0;
}
.app {
  background: #2a2c3c;
  border: 4px solid #fff;
  box-shadow: 8px 8px 0 #000;
  padding: 20px;
  width: min(90vw, 480px);
}
h1 { font-size: 24px; text-transform: uppercase; margin-bottom: 16px; color: #ffd700; text-shadow: 2px 2px 0 #000; }
.counters { display: flex; gap: 16px; margin-bottom: 16px; font-size: 14px; }
.counters p { background: #111; padding: 6px 10px; border: 2px solid #fff; }
.counters span { color: #ffd700; }
#task-form { display: flex; gap: 8px; margin-bottom: 16px; }
#task-form label { position: absolute; left: -9999px; }
#todo-input {
  flex: 1;
  padding: 8px;
  border: 3px solid #fff;
  background: #000;
  color: #fff;
  font-family: inherit;
  outline: none;
}
#todo-input:focus { border-color: #ffd700; }
#todo-add,
.delete-btn {
  padding: 8px 12px;
  border: 3px solid #fff;
  background: #ffd700;
  color: #000;
  font-family: inherit;
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
}
#todo-add:hover,
.delete-btn:hover { background: #fff; }
#todo-add:focus-visible,
.delete-btn:focus-visible,
#todo-input:focus-visible { outline: 3px dashed #ffd700; outline-offset: 2px; }
#todo-list { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.task-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: #111;
  border: 3px solid #fff;
  padding: 8px;
}
.task-row.done { opacity: .6; }
.task-label { display: flex; align-items: center; gap: 8px; flex: 1; }
.task-label input[type="checkbox"] { width: 18px; height: 18px; accent-color: #ffd700; }
.task-label span { word-break: break-word; }
.done span { text-decoration: line-through; }
.delete-btn { background: #ff4444; padding: 4px 8px; font-size: 12px; }
.delete-btn:hover { background: #ff7777; }

const input = document.getElementById('todo-input');
const list = document.getElementById('todo-list');
const totalSpan = document.getElementById('todo-total');
const remainingSpan = document.getElementById('remaining');

let tasks = [];
let nextId = 1;

function render() {
  list.innerHTML = '';
  let remaining = 0;
  for (const task of tasks) {
    if (!task.done) remaining++;
    const li = document.createElement('li');
    li.className = 'task-row' + (task.done ? ' done' : '');
    const label = document.createElement('label');
    label.className = 'task-label';
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.done;
    checkbox.addEventListener('change', () => toggleTask(task.id));
    const span = document.createElement('span');
    span.id = 'todo-text-' + task.id;
    span.textContent = task.text;
    label.append(checkbox, span);
    const del = document.createElement('button');
    del.type = 'button';
    del.id = 'todo-delete-' + task.id;
    del.className = 'delete-btn';
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete ' + task.text);
    del.addEventListener('click', () => deleteTask(task.id));
    li.append(label, del);
    list.appendChild(li);
  }
  totalSpan.textContent = tasks.length;
  remainingSpan.textContent = remaining;
}

function addTask(text) {
  const trimmed = text.trim();
  if (trimmed === '') return;
  tasks.push({ id: nextId++, text: trimmed, done: false });
  render();
}

function toggleTask(id) {
  const task = tasks.find(t => t.id === id);
  if (task) {
    task.done = !task.done;
    render();
  }
}

function deleteTask(id) {
  tasks = tasks.filter(t => t.id !== id);
  render();
}

document.getElementById('task-form').addEventListener('submit', (e) => {
  e.preventDefault();
  addTask(input.value);
  input.value = '';
  input.focus();
});

render();
